function requireConfigured() { if (!isConfigured()) throw new Error('SUPABASE_DB_URL is required for the relational authority layer'); }
function getPool() { requireConfigured(); return getPostgresPool(); }
function parameterize(sql, values = []) {
  let output = '';
  let index = 0;
  let state = 'normal';
  for (let i = 0; i < sql.length; i += 1) {
    const char = sql[i];
    const next = sql[i + 1];
    if (state === 'single') {
      output += char;
      if (char === "'" && next === "'") { output += next; i += 1; }
      else if (char === "'") state = 'normal';
      continue;
    }
    if (state === 'double') {
      output += char;
      if (char === '"' && next === '"') { output += next; i += 1; }
      else if (char === '"') state = 'normal';
      continue;
    }
    if (state === 'line-comment') {
      output += char;
      if (char === '\n') state = 'normal';
      continue;
    }
    if (state === 'block-comment') {
      output += char;
      if (char === '*' && next === '/') { output += next; i += 1; state = 'normal'; }
      continue;
    }
    if (char === "'") { state = 'single'; output += char; continue; }
    if (char === '"') { state = 'double'; output += char; continue; }
    if (char === '-' && next === '-') { state = 'line-comment'; output += char + next; i += 1; continue; }
    if (char === '/' && next === '*') { state = 'block-comment'; output += char + next; i += 1; continue; }
    if (char === '?') { index += 1; output += `$${index}`; continue; }
    output += char;
  }
  if (index !== values.length) throw new Error(`PostgreSQL parameter count mismatch: SQL expects ${index}, received ${values.length}`);
  return output;
}
function adaptResult(result) {
  // A short-lived adapter lets untouched domain functions consume rows while
  // all database I/O itself uses node-postgres result objects.
  result[0] = result.rows;
  result[1] = [];
  return result;
}
function query(sql, values = []) { return getPool().query(parameterize(sql, values), values).then(adaptResult); }
function queryOn(client, sql, values = []) { return client.query(parameterize(sql, values), values).then(adaptResult); }
function newId(prefix) { return `${prefix}_${crypto.randomBytes(12).toString('hex')}`; }
function iso(value) { return value ? new Date(value).toISOString().slice(0, 19).replace('T', ' ') : null; }
function json(value) { return JSON.stringify(value == null ? null : value); }
function parseJson(value, fallback) { try { if (value == null) return fallback; if (typeof value === 'object') return value; return JSON.parse(value); } catch { return fallback; } }

