// Test-only authorization uses the same canonical role grants as persistence.
// Production requests always resolve grants from role_permissions in storage.
function testFixtureRolePermissions(role) {
  const grants = ROLE_PERMISSION_SEED[String(role || '').toUpperCase()];
  return Array.isArray(grants) ? grants.slice() : null;
}

async function migrate() {
  requireConfigured();
  const requiredVersions = ['20261116000000', '20261116001000', '20261116002000'];
  const { rows } = await query(
    'SELECT version::text AS version FROM supabase_migrations.schema_migrations WHERE version = ANY(?::text[])',
    [requiredVersions]
  );
  const applied = new Set(rows.map((row) => row.version));
  const missing = requiredVersions.filter((version) => !applied.has(version));
  if (missing.length) throw new Error('Required Supabase migrations are not applied: ' + missing.join(', '));

  const { rows: relations } = await query(`
    SELECT to_regclass('public.users') AS users,
           to_regclass('public.server_sessions') AS server_sessions,
           EXISTS (
             SELECT 1 FROM information_schema.columns
             WHERE table_schema = 'public' AND table_name = 'users'
               AND column_name = 'supabase_auth_user_id'
           ) AS auth_mapping
  `);
  if (!relations[0]?.users || !relations[0]?.server_sessions || !relations[0]?.auth_mapping) {
    throw new Error('Required EduTrack Supabase authentication relations are missing');
  }
}
// SQL gateway reused by every macro reporting query. Missing consent is OFF.
function synchronizedSchoolPredicate(alias = 's') {
  if (!/^[a-z][a-z0-9_]*$/i.test(alias)) throw new Error('Invalid school alias');
  return `${alias}.active=TRUE AND ${alias}.district_sync_enabled=TRUE AND ${alias}.district_sync_actor_id IS NOT NULL AND ${alias}.district_id IS NOT NULL`;
}
function administrativeIds(authz,key) {return [...new Set((authz.memberships||[]).flatMap(m=>[m.scope?.[key],...(m.scope?.[key+'s']||[])]).filter(Boolean).map(String))];}
function macroHierarchyFilter(authz) {
  const core=administrativeScope.coreRole(authz?.roles?.[0]);
  if(!core)throw Object.assign(new Error('Administrative role required'),{code:'AUTHORIZATION_DENIED'});
  let sql='1=1';const params=[];
  const restrict=(column,values)=>{if(!values.length){sql+=' AND 1=0';return;}sql+=' AND '+column+' IN ('+values.map(()=>'?').join(',')+')';params.push(...values)};
  if(core.level==='NATIONAL')restrict('sync_region.national_tenant_id',(authz.memberships||[]).filter(m=>m.tenantType==='NATIONAL'&&m.tenantId).map(m=>String(m.tenantId)));
  const regions=administrativeIds(authz,'regionId'),districts=administrativeIds(authz,'districtId');
  if(core.level==='REGIONAL'||regions.length)restrict('sync_region.id',regions);
  if(core.level==='DISTRICT'||districts.length)restrict('sync_district.id',districts);
  return {sql,params};
}
function macroSchoolFilter(authz,alias='s') {
  const hierarchy=macroHierarchyFilter(authz);const schoolIds=administrativeIds(authz,'schoolId');
  let sql=synchronizedSchoolPredicate(alias)+' AND '+hierarchy.sql;const params=[...hierarchy.params];
  if(schoolIds.length){sql+=' AND '+alias+'.id IN ('+schoolIds.map(()=>'?').join(',')+')';params.push(...schoolIds)}
  return {sql,params};
}
async function macroHierarchyContext(authz,scope) {
  const filter=macroHierarchyFilter(authz);let where=filter.sql;const params=[...filter.params];
  if(scope.regionId){where+=' AND sync_region.id=?';params.push(scope.regionId)}
  if(scope.districtId){where+=' AND sync_district.id=?';params.push(scope.districtId)}
  const schools=administrativeIds(authz,'schoolId');
  if(schools.length){where+=' AND EXISTS (SELECT 1 FROM schools assigned WHERE assigned.district_id=sync_district.id AND assigned.id IN ('+schools.map(()=>'?').join(',')+'))';params.push(...schools)}
  const rows=await domainRows('SELECT DISTINCT sync_region.id region_id,sync_district.id district_id FROM regions sync_region LEFT JOIN districts sync_district ON sync_district.region_id=sync_region.id WHERE '+where,params);
  return rows[0]||null;
}
async function macroHierarchyRows(authz, kind, regionId) {
  const gate=macroHierarchyFilter(authz);let where=gate.sql;const params=[...gate.params];
  if(regionId){where+=' AND sync_region.id=?';params.push(regionId);}
  const schools=administrativeIds(authz,'schoolId');
  if(schools.length){where+=' AND EXISTS (SELECT 1 FROM schools assigned WHERE assigned.district_id=sync_district.id AND assigned.id IN ('+schools.map(()=>'?').join(',')+'))';params.push(...schools);}
  const projection=kind==='regions'?'sync_region.id,sync_region.name':'sync_district.id,sync_district.region_id AS regionId,sync_district.name';
  if(kind!=='regions')where+=' AND sync_district.id IS NOT NULL';
  return domainRows('SELECT DISTINCT '+projection+' FROM regions sync_region LEFT JOIN districts sync_district ON sync_district.region_id=sync_region.id WHERE '+where+' ORDER BY '+(kind==='regions'?'sync_region.name':'sync_district.name'),params);
}
async function macroSchoolContext(authz, schoolId) {
  const filter=macroSchoolFilter(authz);
  const rows=await domainRows(`SELECT s.id,s.tenant_id,s.district_id,sync_district.region_id FROM schools s JOIN districts sync_district ON sync_district.id=s.district_id JOIN regions sync_region ON sync_region.id=sync_district.region_id WHERE ${filter.sql} AND s.id=?`,[...filter.params,schoolId]);
  return rows[0] || null;
}
// Extend the existing read layer; filter before grouping/ordering/pagination.
// SQL and schoolColumn are application-owned, never supplied by a client.
async function scopedSchoolRows(sql, params, authz, schoolColumn = 'school_id') {
  if (!administrativeScope.coreRole(authz?.roles?.[0])) return domainRows(sql,params);
  if (!/^SELECT\b/i.test(sql) || !/^[a-z_][a-z0-9_]*(\.[a-z_][a-z0-9_]*)?$/i.test(schoolColumn) || /;/.test(sql)) throw new Error('Invalid scoped school query');
  const filter=macroSchoolFilter(authz);
  const predicate=`${schoolColumn} IN (SELECT s.id FROM schools s JOIN districts sync_district ON sync_district.id=s.district_id JOIN regions sync_region ON sync_region.id=sync_district.region_id WHERE ${filter.sql})`;
  const split=sql.search(/\b(GROUP BY|ORDER BY|LIMIT)\b/i);
  const head=split<0?sql:sql.slice(0,split), tail=split<0?'':sql.slice(split);
  return domainRows(head+(/\bWHERE\b/i.test(head)?' AND ':' WHERE ')+predicate+' '+tail,[...(params||[]),...filter.params]);
}
async function schoolDistrictSyncStatus(schoolId) {
  const rows = await domainRows('SELECT id,district_id,district_sync_enabled,district_sync_actor_id,district_sync_updated_at FROM schools WHERE id=? AND active=TRUE', [schoolId]);
  if (!rows.length) throw Object.assign(new Error('School not found'), {code:'NOT_FOUND'});
  const row = rows[0];
  return {schoolId:row.id,districtId:row.district_id,enabled:!!Number(row.district_sync_enabled) && !!row.district_sync_actor_id && !!row.district_id,updatedAt:row.district_sync_updated_at};
}
async function setSchoolDistrictSync(schoolId, enabled, actorId) {
  if (typeof enabled !== 'boolean') throw Object.assign(new Error('enabled must be boolean'), {code:'DOMAIN_VALIDATION'});
  await ensureInitialized();
  const conn = await getPool().connect();
  try {
    await queryOn(conn,'BEGIN');
    const { rows: actors } = await queryOn(conn,"SELECT u.id,tm.scope_json,ro.name role_name FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles ro ON ro.id=ur.role_id AND ro.name IN ('HEADTEACHER','ASSISTANT_HEADTEACHER') JOIN tenant_memberships tm ON tm.user_id=u.id AND tm.active=TRUE JOIN tenants t ON t.id=tm.tenant_id AND t.active=TRUE JOIN schools assigned_school ON assigned_school.id=? AND assigned_school.tenant_id=tm.tenant_id WHERE u.id=? AND u.active=TRUE AND u.status='ACTIVE'", [schoolId,actorId]);
    const authorizedActors=[];
    for(const actor of actors){if(!administrativeScope.isHeadteacherEquivalent(actor.role_name))continue;const source=administrativeScope.permissionSourceRole(actor.role_name);const { rows: grants } = await queryOn(conn,"SELECT 1 FROM roles r JOIN role_permissions rp ON rp.role_id=r.id JOIN permissions p ON p.id=rp.permission_id WHERE r.name=? AND p.name='schools.manage' LIMIT 1",[source]);if(grants.length)authorizedActors.push(actor);}
    const assigned = authorizedActors.some(row => { const scope=parseJson(row.scope_json,{}); return scope.schoolId===schoolId || (scope.schoolIds||[]).includes(schoolId); });
    if (!assigned) throw Object.assign(new Error('Only the assigned Headteacher may change synchronization'), {code:'AUTHORIZATION_DENIED'});
    const { rows: schools } = await queryOn(conn,'SELECT s.id,s.district_id,s.district_sync_enabled,d.region_id FROM schools s LEFT JOIN districts d ON d.id=s.district_id WHERE s.id=? AND s.active=TRUE FOR UPDATE', [schoolId]);
    const school=schools[0];
    if (!school) throw Object.assign(new Error('School not found'), {code:'NOT_FOUND'});
    if (enabled && !school.region_id) throw Object.assign(new Error('School requires a canonical District and Region'), {code:'DOMAIN_VALIDATION'});
    const now=new Date();
    await queryOn(conn,'UPDATE schools SET district_sync_enabled=?,district_sync_actor_id=?,district_sync_updated_at=? WHERE id=?', [enabled,actorId,now,schoolId]);
    await queryOn(conn,'INSERT INTO audit_events (id,event_type,actor_user_id,occurred_at,metadata_json) VALUES (?,?,?,?,?)', [newId('audit'),'SCHOOL_DISTRICT_SYNC_CHANGED',actorId,now,json({schoolId,districtId:school.district_id,regionId:school.region_id,previousEnabled:!!Number(school.district_sync_enabled),enabled,source:'EMS_SYNC'})]);
    await queryOn(conn,'COMMIT');
    return {schoolId,districtId:school.district_id,enabled,updatedAt:now.toISOString()};
  } catch(error) { await queryOn(conn,'ROLLBACK'); throw error; } finally { conn.release(); }
}
async function ensureInitialized() { if (!isConfigured()) return false; if (!initialized) initialized = migrate().catch((error) => { initialized = null; throw error; }); await initialized; return true; }

function rowToUser(row) {
  if (!row) return null;
  return { id: row.id, email: row.email, staffId: row.staff_id, accessCodeHash: row.access_code_hash || '', credentialStatus: row.credential_status || 'ACTIVE', role: row.role_name || null, hierarchy: row.hierarchy, scope: parseJson(row.scope_json, null), active: Boolean(row.active), status: row.status, developmentFixture: Boolean(row.development_fixture), supabaseAuthUserId: row.supabase_auth_user_id || null, createdAt: row.created_at, updatedAt: row.updated_at };
}
const AUTH_USER_SELECT = `SELECT u.*, c.access_code_hash, c.status AS credential_status, r.name AS role_name,
  COALESCE(u.scope_json, tm.scope_json) AS scope_json, COALESCE(u.staff_id, staff.staff_identifier) AS staff_id
  FROM users u LEFT JOIN credentials c ON c.user_id=u.id
  LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id
  LEFT JOIN tenant_memberships tm ON tm.user_id=u.id AND tm.active=TRUE
  LEFT JOIN LATERAL (SELECT staff_identifier FROM staff WHERE user_id=u.id ORDER BY created_at LIMIT 1) staff ON TRUE`;
async function findUser(identifier) {
  await ensureInitialized();
  const { rows } = await query(`${AUTH_USER_SELECT} WHERE u.active=TRUE AND (LOWER(u.email)=LOWER(?) OR LOWER(u.staff_id)=LOWER(?) OR EXISTS (SELECT 1 FROM staff sx WHERE sx.user_id=u.id AND LOWER(sx.staff_identifier)=LOWER(?))) LIMIT 1`, [identifier, identifier, identifier]);
  return rowToUser(rows[0]);
}
async function findUserById(userId){await ensureInitialized();const { rows } = await query(`${AUTH_USER_SELECT} WHERE u.id=? AND u.active=TRUE LIMIT 1`,[userId]);return rowToUser(rows[0]);}
async function findUserByAuthId(authUserId){await ensureInitialized();const { rows } = await query(`${AUTH_USER_SELECT} WHERE u.supabase_auth_user_id=? AND u.active=TRUE LIMIT 1`,[authUserId]);return rowToUser(rows[0]);}
async function authenticateUserSession(identifier,password){if(!isAuthConfigured())throw new Error('Supabase Auth configuration is required');const candidate=await findUser(identifier);if(!candidate?.email||!candidate.supabaseAuthUserId||!candidate.active||candidate.status!=='ACTIVE')return null;let authSession;try{authSession=await supabaseAuth.signInWithPassword(candidate.email,password)}catch(error){if([400,401,422].includes(error.status))return null;throw error}if(String(authSession.user.id)!==String(candidate.supabaseAuthUserId))return null;return {user:candidate,authSession};}
async function authenticateUser(identifier,password){const result=await authenticateUserSession(identifier,password);return result?.user||null;}
async function upsertUser(user) {
  await ensureInitialized();
  if(!user.authPassword)throw new Error('Supabase Auth provisioning requires the original password input');
  const authUser=await supabaseAuth.ensureUser({email:user.email,password:user.authPassword,metadata:{edutrackUserId:String(user.id)}});
  if(!authUser?.id)throw new Error('Supabase Auth provisioning returned no UUID');
  const now=iso(user.updatedAt||new Date()),created=iso(user.createdAt||now);
  await query(`INSERT INTO users (id,email,staff_id,status,active,development_fixture,hierarchy,scope_json,supabase_auth_user_id,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT (id) DO UPDATE SET email=EXCLUDED.email,staff_id=EXCLUDED.staff_id,status=EXCLUDED.status,active=EXCLUDED.active,development_fixture=EXCLUDED.development_fixture,hierarchy=EXCLUDED.hierarchy,scope_json=EXCLUDED.scope_json,supabase_auth_user_id=EXCLUDED.supabase_auth_user_id,updated_at=EXCLUDED.updated_at`, [user.id,user.email,user.staffId||null,user.active===false?'INACTIVE':'ACTIVE',user.active!==false,Boolean(user.developmentFixture),user.hierarchy||null,json(user.scope||null),authUser.id,created,now]);
  await query('INSERT INTO credentials (id,user_id,access_code_hash,status,created_at,updated_at) VALUES (?,?,?,?,?,?) ON CONFLICT (user_id) DO UPDATE SET access_code_hash=EXCLUDED.access_code_hash,status=EXCLUDED.status,updated_at=EXCLUDED.updated_at', [user.credentialId||newId('cred'),user.id,user.accessCodeHash||null,'ACTIVE',created,now]);
  const role = user.role || 'DEVELOPER_ROOT';
  await query('INSERT INTO roles (id,name,description) VALUES (?,?,?) ON CONFLICT DO NOTHING', [`role_${role.toLowerCase()}`, role, `Canonical EduTrack role ${role}`]);
  await query('INSERT INTO user_roles (user_id,role_id) VALUES (?,?) ON CONFLICT (user_id,role_id) DO NOTHING', [user.id, `role_${role.toLowerCase()}`]);
  return { ...user, supabaseAuthUserId: authUser.id };
}
async function provisionDevelopmentAccount(user) { return upsertUser({ ...user, developmentFixture: true, staffId: user.staffId || 'DEV-ROOT', role: 'DEVELOPER_ROOT', hierarchy: 'ALL', scope: ['NATIONAL','REGIONAL','DISTRICT','SCHOOL'] }); }
async function createSession(session) { await ensureInitialized(); await query('INSERT INTO server_sessions (id,token_hash,user_id,created_at,expires_at,login_scope_json) VALUES (?,?,?,?,?,?)', [session.id, session.tokenHash, session.userId, iso(session.createdAt), iso(session.expiresAt), session.loginScope ? json(session.loginScope) : null]); }
async function extendSession(tokenHash, expiresAt) { await ensureInitialized(); await query('UPDATE server_sessions SET expires_at=? WHERE token_hash=? AND revoked_at IS NULL AND expires_at>CURRENT_TIMESTAMP', [iso(expiresAt), tokenHash]); }
async function revokeSessionByHash(tokenHash) { if (!isConfigured()) return; await ensureInitialized(); await query('UPDATE server_sessions SET revoked_at = CURRENT_TIMESTAMP WHERE token_hash = ? AND revoked_at IS NULL', [tokenHash]); }
async function updateSessionCsrf(tokenHash, csrfTokenHash) { await ensureInitialized(); await query('UPDATE server_sessions SET csrf_token_hash=? WHERE token_hash=? AND revoked_at IS NULL AND expires_at>CURRENT_TIMESTAMP', [csrfTokenHash, tokenHash]); }
async function appendAudit(event) { await ensureInitialized(); await query('INSERT INTO audit_events (id,event_type,actor_user_id,occurred_at,correlation_id,ip,user_agent,metadata_json) VALUES (?,?,?,?,?,?,?,?)', [event.id || newId('audit'), event.action || event.eventType, event.userId || null, iso(event.at || new Date()), event.correlationId || null, event.ip || null, event.userAgent || null, json(event)]); }
async function hydrateAuthState(db) {
  if (!isConfigured()) return db;
  await ensureInitialized();
  const { rows: users } = await query(`SELECT u.*, c.access_code_hash, c.status AS credential_status, r.name AS role_name FROM users u LEFT JOIN credentials c ON c.user_id=u.id LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id`);
  db.users = users.map(rowToUser);
  const { rows: sessions } = await query('SELECT id,token_hash AS "tokenHash",user_id AS "userId",created_at AS "createdAt",expires_at AS "expiresAt",revoked_at AS "revokedAt",csrf_token_hash AS "csrfTokenHash",login_scope_json AS "loginScope" FROM server_sessions WHERE revoked_at IS NULL AND expires_at > CURRENT_TIMESTAMP');
  db.sessions = sessions.map(session => ({...session, loginScope:parseJson(session.loginScope,null)}));
  return db;
}
async function findPaymentIntent(userId,idempotencyKey){await ensureInitialized();const { rows: rows } = await query('SELECT * FROM payment_intents WHERE user_id=? AND idempotency_key=? LIMIT 1',[userId,idempotencyKey]);return rows[0]||null;}
