async function importJson(jsonPath) {
  await ensureInitialized();
  const source = JSON.parse(fs.readFileSync(path.resolve(jsonPath), 'utf8'));
  for (const user of source.users || []) await upsertUser(user);
  for (const region of source.regions || []) await query('INSERT INTO regions (id,name) VALUES (?,?) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name', [region.id || newId('reg'), region.name]);
  return { users: (source.users || []).length, regions: (source.regions || []).length, imported: true };
}
async function resolveAuthorization(userId) {
  await ensureInitialized();
  const { rows: users } = await query('SELECT id,status,active,development_fixture,hierarchy FROM users WHERE id=? LIMIT 1', [userId]);
  if (!users.length) return null;
  const { rows: roles } = await query('SELECT r.name FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=?', [userId]);
  const { rows: permissions } = await query('SELECT DISTINCT r.name AS role_name,p.name FROM user_roles ur JOIN roles r ON r.id=ur.role_id JOIN role_permissions rp ON rp.role_id=ur.role_id JOIN permissions p ON p.id=rp.permission_id WHERE ur.user_id=?', [userId]);
  const { rows: memberships } = await query('SELECT tm.tenant_id,tm.scope_json,tm.active,t.tenant_type FROM tenant_memberships tm JOIN tenants t ON t.id=tm.tenant_id AND t.active=TRUE WHERE tm.user_id=?', [userId]);
  const rolePermissions = Object.fromEntries(roles.map(role => [role.name,permissions.filter(p => p.role_name === role.name).map(p => p.name)]));
  for (const role of roles.map(row => row.name)) {
    const source = administrativeScope.permissionSourceRole(role);
    if (source === role) continue;
    if (!Object.prototype.hasOwnProperty.call(rolePermissions, source)) {
      const { rows: sourcePermissions } = await query('SELECT DISTINCT p.name FROM roles r JOIN role_permissions rp ON rp.role_id=r.id JOIN permissions p ON p.id=rp.permission_id WHERE r.name=?', [source]);
      rolePermissions[source] = sourcePermissions.map(row => row.name);
    }
    rolePermissions[role] = [...rolePermissions[source]];
  }
  return { user: users[0], roles: roles.map((row) => row.name), permissions: permissions.map((row) => row.name), rolePermissions, memberships: memberships.filter((row) => row.active).map((row) => ({ tenantId: row.tenant_id, tenantType: row.tenant_type, scope: parseJson(row.scope_json, {}) })) };
}
