async function updateStaff(id,input){await ensureInitialized();const conn=await getPool().connect();try{await queryOn(conn,'BEGIN');const { rows: existingRows } = await queryOn(conn,"SELECT st.*,EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=st.user_id AND r.name='TEACHER') AS is_teacher FROM staff st WHERE st.id=? LIMIT 1 FOR UPDATE",[id]);if(!existingRows.length)return null;const existing=existingRows[0];const activating=String(input.status||existing.status||'').toUpperCase()==='ACTIVE'&&String(existing.status||'').toUpperCase()!=='ACTIVE';await enforceTeacherLimit(conn,input.schoolId||existing.school_id,Boolean(existing.is_teacher)||String(input.staffType||existing.staff_type||'').toUpperCase()==='TEACHER',activating);const fields=[],values=[];for(const [key,column] of Object.entries({fullName:'full_name',phone:'phone',email:'email',staffType:'staff_type',status:'status',schoolId:'school_id',districtId:'district_id',regionId:'region_id'}))if(input[key]!==undefined){fields.push(`${column}=?`);values.push(input[key]);}if(!fields.length){await queryOn(conn,'ROLLBACK');return existing;}values.push(new Date(),id);await queryOn(conn,`UPDATE staff SET ${fields.join(',')},updated_at=? WHERE id=?`,values);await queryOn(conn,'COMMIT');return (await domainRows('SELECT * FROM staff WHERE id=?',[id]))[0]||null;}catch(e){await queryOn(conn,'ROLLBACK');throw e;}finally{conn.release();}}
async function createStudent(input){await ensureInitialized();const conn=await getPool().connect();const id=input.id||newId('student');const now=iso(new Date());try{await queryOn(conn,'BEGIN');await queryOn(conn,'INSERT INTO students (id,admission_number,student_identifier,full_name,date_of_birth,gender,tenant_id,school_id,class_id,admission_date,special_needs,emergency_contact,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[id,input.admissionNumber,input.studentIdentifier,input.fullName,input.dateOfBirth||null,input.gender||null,input.tenantId,input.schoolId,input.classId||null,input.admissionDate||null,input.specialNeeds||null,input.emergencyContact||null,input.status||'ACTIVE',now,now]);if(input.parentUserId){const { rows: parent } = await queryOn(conn,'SELECT u.id FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.id=? AND r.name=\'PARENT\' AND u.active=TRUE',[input.parentUserId]);if(!parent.length)throw new Error('INVALID_PARENT');await queryOn(conn,'INSERT INTO parent_student_relationships (parent_user_id,student_id,relationship_type,active,created_at) VALUES (?,?,?,1,?)',[input.parentUserId,id,input.relationshipType||'PARENT',now]);}await queryOn(conn,'COMMIT');return (await queryOn(conn,'SELECT * FROM students WHERE id=?',[id]))[0][0];}catch(e){await queryOn(conn,'ROLLBACK');throw e;}finally{conn.release();}}
async function updateStudent(id,input,actorId=null){await ensureInitialized();const fields=[];const values=[];const existing=(await domainRows('SELECT id,school_id,status FROM students WHERE id=? LIMIT 1',[id]))[0];if(!existing)return null;for(const [key,column] of Object.entries({fullName:'full_name',dateOfBirth:'date_of_birth',gender:'gender',classId:'class_id',admissionDate:'admission_date',specialNeeds:'special_needs',emergencyContact:'emergency_contact',status:'status'}))if(input[key]!==undefined){fields.push(`${column}=?`);values.push(input[key]);}if(!fields.length)return existing;const now=iso(new Date());const conn=await getPool().connect();try{await queryOn(conn,'BEGIN');if(input.status!==undefined&&String(input.status).toUpperCase()!==String(existing.status||'').toUpperCase())await queryOn(conn,'INSERT INTO student_status_history (id,student_id,school_id,from_status,to_status,changed_at,changed_by,reason,created_at) VALUES (?,?,?,?,?,?,?,?,?)',[newId('studentstatus'),id,existing.school_id,existing.status||null,String(input.status).toUpperCase(),now,actorId,input.reason||null,now]);values.push(now,id);await queryOn(conn,`UPDATE students SET ${fields.join(',')},updated_at=? WHERE id=?`,values);await queryOn(conn,'COMMIT');}catch(e){await queryOn(conn,'ROLLBACK');throw e;}finally{conn.release();}return (await domainRows('SELECT * FROM students WHERE id=?',[id]))[0]||null;}
async function createClass(input){await ensureInitialized();const id=input.id||newId('class');const now=iso(new Date());await query('INSERT INTO classes (id,name,school_id,tenant_id,academic_config_ref,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)',[id,input.name,input.schoolId,input.tenantId,input.academicConfigRef||null,input.status||'ACTIVE',now,now]);return (await domainRows('SELECT * FROM classes WHERE id=?',[id]))[0];}
async function updateClass(id,input){await ensureInitialized();const fields=[];const values=[];for(const [key,column] of Object.entries({name:'name',academicConfigRef:'academic_config_ref',status:'status'}))if(input[key]!==undefined){fields.push(`${column}=?`);values.push(input[key]);}if(!fields.length)return null;values.push(new Date(),id);await query(`UPDATE classes SET ${fields.join(',')},updated_at=? WHERE id=?`,values);return (await domainRows('SELECT * FROM classes WHERE id=?',[id]))[0]||null;}
async function assignStaffSchool(staffId,schoolId){await ensureInitialized();await query('INSERT INTO staff_school_assignments (staff_id,school_id,active,assigned_at) VALUES (?,?,TRUE,?) ON CONFLICT (staff_id,school_id) DO UPDATE SET active=EXCLUDED.active',[staffId,schoolId,new Date()]);await query('UPDATE staff SET school_id=?,updated_at=? WHERE id=?',[schoolId,new Date(),staffId]);return true;}
async function assignTeacherClass(staffId,classId){await ensureInitialized();await query('INSERT INTO teacher_class_assignments (staff_id,class_id,active,assigned_at) VALUES (?,?,TRUE,?) ON CONFLICT (staff_id,class_id) DO UPDATE SET active=EXCLUDED.active',[staffId,classId,new Date()]);return true;}
async function addParentStudent(parentUserId,studentId,relationshipType='PARENT'){await ensureInitialized();await query('INSERT INTO parent_student_relationships (parent_user_id,student_id,relationship_type,active,created_at) VALUES (?,?,?,1,?)',[parentUserId,studentId,relationshipType,new Date()]);return true;}

async function academicRows(sql, params = []) { return domainRows(sql, params); }
async function createAcademicConfig(input, actorId) { await ensureInitialized(); const id=input.id||newId('acadcfg'); const now=iso(new Date()); await query('INSERT INTO academic_configurations (id,tenant_id,school_id,academic_year,term,week,opening_date,closing_date,status,metadata_json,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',[id,input.tenantId,input.schoolId,input.academicYear,input.term,input.week||null,input.openingDate,input.closingDate,input.status||'DRAFT',json(input.metadata||null),actorId||null,now,now]); return (await academicRows('SELECT * FROM academic_configurations WHERE id=?',[id]))[0]; }
async function updateAcademicConfig(id,input) { await ensureInitialized(); const map={academicYear:'academic_year',term:'term',week:'week',openingDate:'opening_date',closingDate:'closing_date',status:'status',metadata:'metadata_json'}; const fields=[],values=[]; for(const [k,c] of Object.entries(map)) if(input[k]!==undefined){fields.push(c+'=?');values.push(k==='metadata'?json(input[k]):input[k]);} if(!fields.length)return (await academicRows('SELECT * FROM academic_configurations WHERE id=?',[id]))[0]||null; values.push(new Date(),id); await query('UPDATE academic_configurations SET '+fields.join(',')+',updated_at=? WHERE id=?',values); return (await academicRows('SELECT * FROM academic_configurations WHERE id=?',[id]))[0]||null; }
