async function createAttendance(input,actorId){await ensureInitialized();const conn=await getPool().connect();try{await queryOn(conn,'BEGIN');const now=iso(new Date());const type=input.registerType||'STUDENT';const { rows: existing } = await queryOn(conn,'SELECT id FROM attendance_registers WHERE class_id=? AND attendance_date=? AND register_type=? FOR UPDATE',[input.classId,input.attendanceDate,type]);const id=input.id||(existing[0]&&existing[0].id)||newId('attreg');if(existing.length){await queryOn(conn,'UPDATE attendance_registers SET academic_config_id=?,updated_at=? WHERE id=?',[input.academicConfigId||null,now,id]);}else{await queryOn(conn,'INSERT INTO attendance_registers (id,tenant_id,school_id,class_id,academic_config_id,attendance_date,register_type,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?)',[id,input.tenantId,input.schoolId,input.classId,input.academicConfigId||null,input.attendanceDate,type,actorId||null,now,now]);}for(const rec of input.records||[])await queryOn(conn,'INSERT INTO student_attendance_records (id,register_id,student_id,status,note,recorded_by,recorded_at,updated_at) VALUES (?,?,?,?,?,?,?,?) ON CONFLICT (register_id,student_id) DO UPDATE SET status=EXCLUDED.status,note=EXCLUDED.note,recorded_by=EXCLUDED.recorded_by,updated_at=EXCLUDED.updated_at',[newId('att'),id,rec.studentId,rec.status,rec.note||null,actorId||null,now,now]);await queryOn(conn,'COMMIT');return (await domainRows('SELECT * FROM attendance_registers WHERE id=?',[id]))[0];}catch(e){await queryOn(conn,'ROLLBACK');throw e;}finally{conn.release();}}
