async function getStudentQuiz(quizId,userId){await ensureInitialized();const qs=await domainRows("SELECT q.id,q.title,q.duration_seconds FROM quizzes q JOIN students s ON s.class_id=q.class_id AND s.user_id=? AND s.status='ACTIVE' WHERE q.id=? AND q.status='PUBLISHED' LIMIT 1",[userId,quizId]);if(!qs.length)return null;await query("INSERT INTO quiz_attempts (id,quiz_id,student_user_id,started_at,status) VALUES (?,?,?,?, 'IN_PROGRESS') ON CONFLICT (quiz_id,student_user_id) DO NOTHING",[newId('attempt'),quizId,userId,new Date()]);const q=await domainRows('SELECT id,prompt,question_type,options_json,points,position_no FROM quiz_questions WHERE quiz_id=? ORDER BY position_no',[quizId]);return {quiz:qs[0],questions:q.map(x=>({...x,options:parseJson(x.options_json,[])}))};}
async function submitStudentQuiz(input,userId){await ensureInitialized();const conn=await getPool().connect();try{await queryOn(conn,'BEGIN');const { rows: a } = await queryOn(conn,'SELECT * FROM quiz_attempts WHERE quiz_id=? AND student_user_id=? FOR UPDATE',[input.quizId,userId]);if(!a.length)throw new Error('QUIZ_ATTEMPT_NOT_FOUND');if(a[0].status==='SUBMITTED')return {attempt:a[0],alreadyGraded:true};const { rows: questions } = await queryOn(conn,'SELECT id,correct_answer,points FROM quiz_questions WHERE quiz_id=? ORDER BY position_no',[input.quizId]);const answers=input.answers&&typeof input.answers==='object'?input.answers:{};let score=0,total=0;for(const q of questions){const answer=answers[q.id]==null?'':String(answers[q.id]);const correct=answer===String(q.correct_answer==null?'':q.correct_answer);const pts=correct?Number(q.points||0):0;score+=pts;total+=Number(q.points||0);await queryOn(conn,'INSERT INTO quiz_responses (id,attempt_id,question_id,answer_value,is_correct,points_awarded,created_at) VALUES (?,?,?,?,?,?,?) ON CONFLICT (attempt_id,question_id) DO UPDATE SET answer_value=EXCLUDED.answer_value,is_correct=EXCLUDED.is_correct,points_awarded=EXCLUDED.points_awarded',[newId('response'),a[0].id,q.id,answer,correct,pts,new Date()]);}const pct=total?Number((score/total*100).toFixed(2)):0;await queryOn(conn,'UPDATE quiz_attempts SET submitted_at=?,score=?,points_possible=?,percentage=?,status=\'SUBMITTED\' WHERE id=?',[new Date(),score,total,pct,a[0].id]);await queryOn(conn,'COMMIT');return {attempt:{id:a[0].id,quiz_id:input.quizId,score,points_possible:total,percentage:pct,status:'SUBMITTED',submitted_at:new Date().toISOString()},alreadyGraded:false};}catch(e){await queryOn(conn,'ROLLBACK');throw e;}finally{conn.release();}}
