// Part 3 extends the existing relational authority and Part 2 consent gate.
function districtIdsFor(authz) {
  if(administrativeScope.coreRole(authz?.roles?.[0])?.level!=='DISTRICT')throw Object.assign(new Error('District role required'),{code:'AUTHORIZATION_DENIED'});
  return [...new Set((authz.memberships||[]).flatMap(m=>[m.scope?.districtId,...(m.scope?.districtIds||[])]).filter(Boolean).map(String))];
}
async function districtDashboardContext(authz) {
  const ids=districtIdsFor(authz);
  const districts=ids.length?await domainRows(`SELECT d.id,d.name,d.region_id,r.name region_name FROM districts d JOIN regions r ON r.id=d.region_id WHERE d.id IN (${ids.map(()=>'?').join(',')}) ORDER BY d.name`,ids):[];
  const role=authz.roles[0];
  return {role,label:administrativeScope.CORE_ROLES[role].label,districts,permissions:authz.rolePermissions?.[role]||authz.permissions||[]};
}
async function districtDashboardData(authz,districtId,view,schoolId) {
  if(!districtIdsFor(authz).includes(String(districtId)))throw Object.assign(new Error('District scope denied'),{code:'AUTHORIZATION_DENIED'});
  const gate=macroSchoolFilter(authz);
  const where=gate.sql+' AND s.district_id=?'+(schoolId?' AND s.id=?':'');
  const params=[...gate.params,districtId,...(schoolId?[schoolId]:[])];
  const from=` FROM schools s JOIN districts sync_district ON sync_district.id=s.district_id JOIN regions sync_region ON sync_region.id=sync_district.region_id `;
  if(schoolId){const eligible=await domainRows('SELECT s.id'+from+'WHERE '+where,params);if(!eligible.length)throw Object.assign(new Error('School synchronization or District scope denied'),{code:'AUTHORIZATION_DENIED'});}
  if(view==='sports'){
    const rows=await domainRows('SELECT sr.id,sr.record_type,sr.payload_json,s.id school_id,s.name school_name'+from+'JOIN district_sports_records sr ON sr.school_id=s.id AND sr.district_id=s.district_id WHERE '+where+' ORDER BY sr.created_at DESC',params);
    return {records:rows.map(r=>({...((typeof r.payload_json==='string'?JSON.parse(r.payload_json):r.payload_json)||{}),id:r.id,type:r.record_type,schoolId:r.school_id,school:r.school_name,district:districtId}))};
  }
  if(view==='attendance')return {rows:await domainRows(`SELECT s.id school_id,s.name school,COUNT(ar.id) registers,COUNT(DISTINCT ar.attendance_date) reporting_days${from}LEFT JOIN attendance_registers ar ON ar.school_id=s.id WHERE ${where} GROUP BY s.id,s.name ORDER BY s.name`,params)};
  if(view==='examinations')return {rows:await domainRows(`SELECT s.id school_id,s.name school,COUNT(DISTINCT e.id) examinations,COUNT(DISTINCT pr.id) published_results${from}LEFT JOIN examinations e ON e.school_id=s.id LEFT JOIN published_results pr ON pr.school_id=s.id AND pr.publication_status='PUBLISHED' WHERE ${where} GROUP BY s.id,s.name ORDER BY s.name`,params)};
  // Coverage has no operational joins and never returns unsynchronized School identities.
  const schoolIds=[...new Set((authz.memberships||[]).flatMap(m=>[m.scope?.schoolId,...(m.scope?.schoolIds||[])]).filter(Boolean).map(String))];
  const coverageWhere='s.active=TRUE AND s.district_id=?'+(schoolIds.length?` AND s.id IN (${schoolIds.map(()=>'?').join(',')})`:'');
  const [coverage]=await domainRows(`SELECT COUNT(*) total,SUM(CASE WHEN ${synchronizedSchoolPredicate('s')} THEN 1 ELSE 0 END) synchronized FROM schools s WHERE ${coverageWhere}`,[districtId,...schoolIds]);
  const total=Number(coverage.total||0),synchronized=Number(coverage.synchronized||0);
  const schools=await domainRows('SELECT s.id school_id,s.name school'+from+'WHERE '+where+' ORDER BY s.name',params);
  const summary=await multiSchoolSummary({role:authz.roles[0],districtIds:[districtId],authorization:authz,filters:{schoolId}});
  return {coverage:{total,synchronized,notSynchronized:total-synchronized,reportingCoverage:`${synchronized}/${total}`,scope:schoolIds.length?'assigned Schools within District':'District'},schools,operationalTotals:{students:summary.totals.students,teachers:summary.totals.teachers}};
}
async function createDistrictSportsRecord(authz,input,actorId) {
  const types=['calendar','competitions','athletes','coaches','equipment','tournaments'];
  if(!types.includes(input.type)||!input.schoolId||!input.districtId||!input.record||typeof input.record!=='object'||Array.isArray(input.record))throw Object.assign(new Error('Invalid sports record'),{code:'DOMAIN_VALIDATION'});
  if(!districtIdsFor(authz).includes(String(input.districtId)))throw Object.assign(new Error('District scope denied'),{code:'AUTHORIZATION_DENIED'});
  const record={};for(const [key,value] of Object.entries(input.record)){if(!/^[a-zA-Z][a-zA-Z0-9]{0,39}$/.test(key)||!['string','number'].includes(typeof value)||String(value).length>2000)throw Object.assign(new Error('Invalid sports field'),{code:'DOMAIN_VALIDATION'});if(!['id','type','district','school','schoolId','districtId','createdBy'].includes(key))record[key]=value;}
  const required={calendar:'eventName',competitions:'competitionName',athletes:'studentName',coaches:'coachName',equipment:'equipmentType',tournaments:'tournamentName'}[input.type];
  if(typeof record[required]!=='string'||!record[required].trim()||record[required].length>255)throw Object.assign(new Error('A valid '+required+' is required'),{code:'DOMAIN_VALIDATION'});
  for(const key of ['quantity','schoolsCount'])if(record[key]!==undefined&&(!Number.isFinite(record[key])||record[key]<0))throw Object.assign(new Error('Invalid '+key),{code:'DOMAIN_VALIDATION'});
  const gate=macroSchoolFilter(authz);const conn=await getPool().connect();
  try{await queryOn(conn,'BEGIN');
    const { rows: schools } = await queryOn(conn,`SELECT s.id FROM schools s JOIN districts sync_district ON sync_district.id=s.district_id JOIN regions sync_region ON sync_region.id=sync_district.region_id WHERE ${gate.sql} AND s.id=? AND s.district_id=? FOR UPDATE`,[...gate.params,input.schoolId,input.districtId]);
    if(!schools.length)throw Object.assign(new Error('School synchronization or District scope denied'),{code:'AUTHORIZATION_DENIED'});
    const id=newId('sport');
    await queryOn(conn,'INSERT INTO district_sports_records (id,district_id,school_id,record_type,payload_json,created_by,created_at) VALUES (?,?,?,?,?,?,CURRENT_TIMESTAMP)',[id,input.districtId,input.schoolId,input.type,JSON.stringify(record),actorId]);
    await queryOn(conn,'INSERT INTO audit_events (id,event_type,actor_user_id,occurred_at,metadata_json) VALUES (?,?,?,CURRENT_TIMESTAMP,?)',[newId('audit'),'DISTRICT_SPORTS_CREATED',actorId,JSON.stringify({recordId:id,districtId:input.districtId,schoolId:input.schoolId,type:input.type})]);
    await queryOn(conn,'COMMIT');return {id};
  }catch(error){await queryOn(conn,'ROLLBACK');throw error;}finally{conn.release();}
}

// Part 4 adds permissions only; existing hierarchy, consent and Sports tables remain canonical.
async function upperDashboardContext(authz) {
  const role=authz.roles[0],core=administrativeScope.coreRole(role);
  if(!['REGIONAL','NATIONAL'].includes(core?.level))throw Object.assign(new Error('Regional or National role required'),{code:'AUTHORIZATION_DENIED'});
  const filter=macroHierarchyFilter(authz);
  const assigned=administrativeIds(authz,'schoolId');if(assigned.length){filter.sql+=' AND EXISTS (SELECT 1 FROM schools assigned WHERE assigned.district_id=sync_district.id AND assigned.id IN ('+assigned.map(()=>'?').join(',')+'))';filter.params.push(...assigned)}
  const regions=await domainRows('SELECT DISTINCT sync_region.id,sync_region.name,sync_region.national_tenant_id FROM regions sync_region LEFT JOIN districts sync_district ON sync_district.region_id=sync_region.id WHERE '+filter.sql+' ORDER BY sync_region.name',filter.params);
  const roots=[...new Set((authz.memberships||[]).filter(m=>m.tenantType==='NATIONAL').map(m=>String(m.tenantId)))];
  const nationals=core.level==='NATIONAL'&&roots.length?await domainRows('SELECT id,name FROM tenants WHERE active=TRUE AND tenant_type=\'NATIONAL\' AND id IN ('+roots.map(()=>'?').join(',')+')',roots):[];
  return {role,level:core.level,label:core.label,regions,nationals,permissions:authz.rolePermissions?.[role]||authz.permissions||[]};
}
async function upperDashboardData(authz,view,scope={}) {
  const core=administrativeScope.coreRole(authz?.roles?.[0]);
  if(!['REGIONAL','NATIONAL'].includes(core?.level))throw Object.assign(new Error('Regional or National role required'),{code:'AUTHORIZATION_DENIED'});
  const denied=()=>Object.assign(new Error('Administrative hierarchy or synchronization scope denied'),{code:'AUTHORIZATION_DENIED'});
  if(scope.nationalId){const roots=(authz.memberships||[]).filter(m=>m.tenantType==='NATIONAL').map(m=>String(m.tenantId));if(core.level!=='NATIONAL'||!roots.includes(String(scope.nationalId)))throw denied()}
  if((scope.regionId||scope.districtId)&&!await macroHierarchyContext(authz,scope))throw denied();
  const hierarchy=macroHierarchyFilter(authz);let extra='';const extraParams=[];
  for(const [key,column] of [['nationalId','sync_region.national_tenant_id'],['regionId','sync_region.id'],['districtId','sync_district.id']])if(scope[key]){extra+=' AND '+column+'=?';extraParams.push(scope[key])}
  const institutionWhere=hierarchy.sql+extra;
  const entities=await domainRows('SELECT sync_region.id region_id,sync_region.name region,sync_district.id district_id,sync_district.name district FROM regions sync_region LEFT JOIN districts sync_district ON sync_district.region_id=sync_region.id WHERE '+institutionWhere,[...hierarchy.params,...extraParams]);
  if((scope.regionId||scope.districtId)&&!entities.length)throw denied();
  const gate=macroSchoolFilter(authz);let where=gate.sql+extra;const params=[...gate.params,...extraParams];
  if(scope.schoolId){where+=' AND s.id=?';params.push(scope.schoolId)}
  const from=' FROM schools s JOIN districts sync_district ON sync_district.id=s.district_id JOIN regions sync_region ON sync_region.id=sync_district.region_id ';
  const schools=await domainRows('SELECT s.id school_id,s.name school,s.district_id,sync_region.id region_id'+from+'WHERE '+where+' ORDER BY s.name',params);
  if(scope.schoolId&&!schools.length)throw denied();
  if(view==='attendance')return {rows:await domainRows('SELECT s.id school_id,s.name school,COUNT(ar.id) registers,COUNT(DISTINCT ar.attendance_date) reporting_days'+from+'LEFT JOIN attendance_registers ar ON ar.school_id=s.id WHERE '+where+' GROUP BY s.id,s.name ORDER BY s.name',params)};
  if(view==='examinations')return {rows:await domainRows("SELECT s.id school_id,s.name school,COUNT(DISTINCT e.id) examinations,COUNT(DISTINCT pr.id) published_results"+from+"LEFT JOIN examinations e ON e.school_id=s.id LEFT JOIN published_results pr ON pr.school_id=s.id AND pr.publication_status='PUBLISHED' WHERE "+where+' GROUP BY s.id,s.name ORDER BY s.name',params)};
  // No personal Sports payload is selected or returned at higher levels.
  if(view==='sports')return {rows:await domainRows('SELECT s.id school_id,s.name school,sr.record_type,COUNT(sr.id) records'+from+'JOIN district_sports_records sr ON sr.school_id=s.id AND sr.district_id=s.district_id WHERE '+where+' GROUP BY s.id,s.name,sr.record_type ORDER BY s.name,sr.record_type',params)};
  const assignedSchools=administrativeIds(authz,'schoolId');
  let metadataWhere='s.active=TRUE AND '+institutionWhere;const metadataParams=[...hierarchy.params,...extraParams];
  if(assignedSchools.length){metadataWhere+=' AND s.id IN ('+assignedSchools.map(()=>'?').join(',')+')';metadataParams.push(...assignedSchools)}
  // Institution/consent metadata only. Unsynchronized School IDs never leave this function.
  const metadata=await domainRows('SELECT s.id,s.district_id,sync_region.id region_id,CASE WHEN '+synchronizedSchoolPredicate('s')+' THEN 1 ELSE 0 END eligible'+from+'WHERE '+metadataWhere,metadataParams);
  const regionMap=new Map(),districtMap=new Map();
  for(const e of entities){regionMap.set(e.region_id,{id:e.region_id,name:e.region,totalSchools:0,synchronizedSchools:0});if(e.district_id)districtMap.set(e.district_id,{id:e.district_id,name:e.district,regionId:e.region_id,totalSchools:0,synchronizedSchools:0})}
  if(assignedSchools.length){const regions=new Set(metadata.map(s=>s.region_id)),districts=new Set(metadata.map(s=>s.district_id));for(const id of regionMap.keys())if(!regions.has(id))regionMap.delete(id);for(const id of districtMap.keys())if(!districts.has(id))districtMap.delete(id)}
  for(const school of metadata)for(const entry of [regionMap.get(school.region_id),districtMap.get(school.district_id)])if(entry){entry.totalSchools++;entry.synchronizedSchools+=Number(school.eligible)}
  const total=metadata.length,synchronized=metadata.filter(s=>Number(s.eligible)).length;
  const coverage={total,synchronized,notSynchronized:total-synchronized,reportingCoverage:`${synchronized}/${total}`,scope:assignedSchools.length?'assigned Schools within jurisdiction':core.level==='REGIONAL'?'Region':'National jurisdiction',totalRegions:regionMap.size,contributingRegions:[...regionMap.values()].filter(r=>r.synchronizedSchools>0).length,totalDistricts:districtMap.size,contributingDistricts:[...districtMap.values()].filter(d=>d.synchronizedSchools>0).length};
  const [totals]=await domainRows("SELECT COUNT(DISTINCT st.id) students,COUNT(DISTINCT sf.id) teachers"+from+"LEFT JOIN students st ON st.school_id=s.id AND st.status='ACTIVE' LEFT JOIN staff sf ON sf.school_id=s.id AND sf.status='ACTIVE' WHERE "+where,params);
  return {coverage,regions:[...regionMap.values()],districts:[...districtMap.values()],schools:['schools','export'].includes(view)?schools:[],operationalTotals:{students:Number(totals.students||0),teachers:Number(totals.teachers||0)}};
}
